-- Settlements directory rebuilt from the official SOATE 2026 classifier
-- (scripts/cities/build-cities.py): stable soate_code key, ru + proper kg names,
-- coordinates for every settlement. Trips and passenger requests now reference
-- places by id (FK) instead of free-text names — homonyms (12 × «Кара-Суу»)
-- are finally distinguishable — and pickup / dropoff stops move to trip_stops.
-- The name columns on trips / requests stay as a display snapshot (name_ru).

-- RU/KG folding used for name matching and trigram search:
-- lower, Дж→Ж (the directory spells Жалал-Абад), ё/ө/ү/ң → е/о/у/н.
CREATE OR REPLACE FUNCTION kg_fold(text) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE
AS $$ SELECT translate(replace(lower($1), 'дж', 'ж'), 'ёөүң', 'еоун') $$;

CREATE OR REPLACE FUNCTION kg_fold_array(text[]) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE
AS $$ SELECT kg_fold(array_to_string($1, ' ')) $$;

-- ─── 1. New directory ────────────────────────────────────────────────
CREATE TABLE "cities_new" (
  "id"            SERIAL PRIMARY KEY,
  "soate_code"    VARCHAR(20) NOT NULL UNIQUE,
  "parent_soate"  VARCHAR(20),
  "type"          VARCHAR(20) NOT NULL,
  "parent_id"     INTEGER,
  "oblast_id"     INTEGER,
  "raion_id"      INTEGER,
  "name_ru"       VARCHAR(150) NOT NULL,
  "name_kg"       VARCHAR(150) NOT NULL,
  "aliases"       TEXT[] NOT NULL DEFAULT '{}',
  "lat"           DOUBLE PRECISION,
  "lng"           DOUBLE PRECISION,
  "coord_approx"  BOOLEAN NOT NULL DEFAULT false,
  "osm_type"      VARCHAR(10),
  "osm_id"        BIGINT,
  "priority"      INTEGER NOT NULL DEFAULT 0,
  "is_searchable" BOOLEAN NOT NULL DEFAULT true,
  "is_active"     BOOLEAN NOT NULL DEFAULT true
);

