ON CONFLICT (soate_code) DO UPDATE SET
  parent_soate = EXCLUDED.parent_soate, type = EXCLUDED.type,
  name_ru = EXCLUDED.name_ru, name_kg = EXCLUDED.name_kg, aliases = EXCLUDED.aliases,
  lat = EXCLUDED.lat, lng = EXCLUDED.lng, coord_approx = EXCLUDED.coord_approx,
  osm_type = EXCLUDED.osm_type, osm_id = EXCLUDED.osm_id,
  priority = EXCLUDED.priority, is_searchable = EXCLUDED.is_searchable;

UPDATE "cities_new" c SET parent_id = p.id
  FROM "cities_new" p WHERE p.soate_code = c.parent_soate AND c.parent_id IS DISTINCT FROM p.id;
UPDATE "cities_new" c SET
  oblast_id = (SELECT o.id FROM "cities_new" o
               WHERE o.soate_code = '417' || substr(c.soate_code, 4, 2) || '000000000'
                 AND o.id <> c.id),
  raion_id = (SELECT r.id FROM "cities_new" r
              WHERE r.soate_code = '417' || substr(c.soate_code, 4, 5) || '000000'
                AND r.type IN ('raion', 'city_district') AND r.id <> c.id)
  WHERE c.soate_code LIKE '417%';
-- Non-SOATE rows (osm:* villages, airport:*) hang off a raion or an oblast.
UPDATE "cities_new" c SET
  raion_id = CASE WHEN p.type = 'raion' THEN p.id END,
  oblast_id = CASE WHEN p.type = 'oblast' THEN p.id ELSE p.oblast_id END
  FROM "cities_new" p WHERE c.soate_code NOT LIKE '417%' AND p.id = c.parent_id;


-- ─── 2. Map every place name used by trips / requests to a directory row ──
-- Ranking: an exact name beats an alias; a city / town beats a village (trips
-- are overwhelmingly between towns); homonym villages resolve to the candidate
-- nearest to where the OLD directory row with that name was.
CREATE TEMP TABLE used_names AS
  SELECT DISTINCT n AS name FROM (
    SELECT origin_city AS n FROM trips UNION ALL SELECT destination_city FROM trips
    UNION ALL SELECT unnest(pickup_cities) FROM trips
    UNION ALL SELECT unnest(dropoff_cities) FROM trips
    UNION ALL SELECT origin_city FROM passenger_requests
    UNION ALL SELECT destination_city FROM passenger_requests
  ) s WHERE n IS NOT NULL AND n <> '';

CREATE TEMP TABLE name_map AS
  SELECT DISTINCT ON (u.name) u.name, c.id AS city_id
  FROM used_names u
  JOIN cities_new c
    ON c.is_searchable
   AND (kg_fold(c.name_ru) = kg_fold(u.name) OR kg_fold(c.name_kg) = kg_fold(u.name)
        OR kg_fold(u.name) = ANY (SELECT kg_fold(a) FROM unnest(c.aliases) a))
  LEFT JOIN LATERAL (
    SELECT o.lat, o.lng FROM cities o
    WHERE o.name_ru = u.name AND o.lat IS NOT NULL
    ORDER BY (o.type IN ('city', 'town')) DESC, o.priority DESC, o.id LIMIT 1
  ) old ON true
  ORDER BY u.name,
           (kg_fold(c.name_ru) = kg_fold(u.name) OR kg_fold(c.name_kg) = kg_fold(u.name)) DESC,
           (c.type IN ('capital', 'city', 'town')) DESC,
           CASE WHEN old.lat IS NULL OR c.lat IS NULL THEN 0
                ELSE (c.lat - old.lat) ^ 2 + (c.lng - old.lng) ^ 2 END,
           c.priority DESC, c.id;

-- Names the directory doesn't know (typos, retired places): closest by trigram.
-- Each one is reported in the deploy log for a manual check.
INSERT INTO name_map (name, city_id)
  SELECT u.name, (
    SELECT c.id FROM cities_new c WHERE c.is_searchable
    ORDER BY similarity(kg_fold(c.name_ru), kg_fold(u.name)) DESC, c.priority DESC, c.id
    LIMIT 1)
  FROM used_names u
  WHERE NOT EXISTS (SELECT 1 FROM name_map m WHERE m.name = u.name);
DO $$
DECLARE r record;
BEGIN
  FOR r IN
    SELECT m.name, c.name_ru, similarity(kg_fold(c.name_ru), kg_fold(m.name)) AS sim
    FROM name_map m JOIN cities_new c ON c.id = m.city_id
    WHERE kg_fold(c.name_ru) <> kg_fold(m.name) AND kg_fold(c.name_kg) <> kg_fold(m.name)
      AND NOT kg_fold(m.name) = ANY (SELECT kg_fold(a) FROM unnest(c.aliases) a)
  LOOP
    RAISE NOTICE 'place name "%" mapped by similarity to "%" (%.2f) — please check', r.name, r.name_ru, r.sim;
  END LOOP;
END $$;

-- ─── 3. Trips ────────────────────────────────────────────────────────
DROP INDEX IF EXISTS "idx_trips_route_day_unique";
DROP INDEX IF EXISTS "idx_trips_active_search";
DROP INDEX IF EXISTS "idx_trips_search";
DROP INDEX IF EXISTS "idx_trips_pickup_cities";
DROP INDEX IF EXISTS "idx_trips_dropoff_cities";
DROP INDEX IF EXISTS "trips_status_idx";

ALTER TABLE "trips"
  ADD COLUMN "origin_city_id" INTEGER,
  ADD COLUMN "destination_city_id" INTEGER,
  ADD COLUMN "destination_address" VARCHAR(200),
  ADD COLUMN "destination_lat" DOUBLE PRECISION,
  ADD COLUMN "destination_lng" DOUBLE PRECISION,
  ALTER COLUMN "origin_city" TYPE VARCHAR(150),
  ALTER COLUMN "destination_city" TYPE VARCHAR(150),
  ALTER COLUMN "origin_address" DROP NOT NULL;

UPDATE "trips" t SET
  origin_city_id = (SELECT city_id FROM name_map WHERE name = t.origin_city),
  destination_city_id = (SELECT city_id FROM name_map WHERE name = t.destination_city);

-- The direct-trip path used to copy the city name into origin_address.
UPDATE "trips" SET origin_address = NULL WHERE origin_address = origin_city;

CREATE TABLE "trip_stops" (
  "id"       UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  "trip_id"  UUID NOT NULL,
  "city_id"  INTEGER NOT NULL,
  "kind"     VARCHAR(10) NOT NULL CHECK ("kind" IN ('pickup', 'dropoff')),
  "position" SMALLINT NOT NULL,
  CONSTRAINT "trip_stops_trip_kind_city_key" UNIQUE ("trip_id", "kind", "city_id"),
  CONSTRAINT "trip_stops_trip_id_fkey" FOREIGN KEY ("trip_id") REFERENCES "trips"("id")
    ON DELETE CASCADE ON UPDATE CASCADE
);

INSERT INTO "trip_stops" (trip_id, city_id, kind, position)
  SELECT DISTINCT ON (t.id, m.city_id, s.kind) t.id, m.city_id, s.kind, s.pos::smallint
  FROM trips t
  CROSS JOIN LATERAL (
    SELECT 'pickup' AS kind, p.n, p.pos FROM unnest(t.pickup_cities) WITH ORDINALITY p(n, pos)
    UNION ALL
    SELECT 'dropoff', d.n, d.pos FROM unnest(t.dropoff_cities) WITH ORDINALITY d(n, pos)
  ) s
  JOIN name_map m ON m.name = s.n
  WHERE m.city_id NOT IN (t.origin_city_id, t.destination_city_id)
  ORDER BY t.id, m.city_id, s.kind, s.pos;

ALTER TABLE "trips"
  DROP COLUMN "pickup_cities",
  DROP COLUMN "dropoff_cities",
  DROP COLUMN "waypoints",
  ALTER COLUMN "origin_city_id" SET NOT NULL,
  ALTER COLUMN "destination_city_id" SET NOT NULL;

-- ─── 4. Passenger requests ───────────────────────────────────────────
DROP INDEX IF EXISTS "idx_requests_route_day_unique";
DROP INDEX IF EXISTS "idx_requests_open_search";
DROP INDEX IF EXISTS "passenger_requests_origin_city_destination_city_status_idx";

ALTER TABLE "passenger_requests"
  ADD COLUMN "origin_city_id" INTEGER,
  ADD COLUMN "destination_city_id" INTEGER,
  ADD COLUMN "origin_address" VARCHAR(200),
  ADD COLUMN "origin_lat" DOUBLE PRECISION,
  ADD COLUMN "origin_lng" DOUBLE PRECISION,
  ADD COLUMN "destination_address" VARCHAR(200),
  ADD COLUMN "destination_lat" DOUBLE PRECISION,
  ADD COLUMN "destination_lng" DOUBLE PRECISION,
  ALTER COLUMN "origin_city" TYPE VARCHAR(150),
  ALTER COLUMN "destination_city" TYPE VARCHAR(150);

UPDATE "passenger_requests" r SET
  origin_city_id = (SELECT city_id FROM name_map WHERE name = r.origin_city),
  destination_city_id = (SELECT city_id FROM name_map WHERE name = r.destination_city);

ALTER TABLE "passenger_requests"
  ALTER COLUMN "origin_city_id" SET NOT NULL,
  ALTER COLUMN "destination_city_id" SET NOT NULL;

-- Display snapshots follow the directory spelling.
UPDATE "trips" t SET origin_city = c.name_ru FROM cities_new c WHERE c.id = t.origin_city_id AND t.origin_city <> c.name_ru;
UPDATE "trips" t SET destination_city = c.name_ru FROM cities_new c WHERE c.id = t.destination_city_id AND t.destination_city <> c.name_ru;
UPDATE "passenger_requests" r SET origin_city = c.name_ru FROM cities_new c WHERE c.id = r.origin_city_id AND r.origin_city <> c.name_ru;
UPDATE "passenger_requests" r SET destination_city = c.name_ru FROM cities_new c WHERE c.id = r.destination_city_id AND r.destination_city <> c.name_ru;

-- ─── 5. Swap the directory in ────────────────────────────────────────
DROP TABLE "cities";
DROP FUNCTION IF EXISTS cities_prompt_folded(text[]);
ALTER TABLE "cities_new" RENAME TO "cities";
ALTER TABLE "cities" DROP COLUMN "parent_soate";
ALTER SEQUENCE "cities_new_id_seq" RENAME TO "cities_id_seq";
ALTER TABLE "cities" RENAME CONSTRAINT "cities_new_pkey" TO "cities_pkey";
ALTER TABLE "cities" RENAME CONSTRAINT "cities_new_soate_code_key" TO "cities_soate_code_key";

ALTER TABLE "cities"
  ADD CONSTRAINT "cities_type_check" CHECK ("type" IN
    ('oblast', 'capital', 'city_district', 'raion', 'city', 'town', 'aiyl_aimak', 'village', 'airport')),
  ADD CONSTRAINT "cities_parent_id_fkey" FOREIGN KEY ("parent_id") REFERENCES "cities"("id") ON DELETE SET NULL ON UPDATE CASCADE,
  ADD CONSTRAINT "cities_oblast_id_fkey" FOREIGN KEY ("oblast_id") REFERENCES "cities"("id") ON DELETE SET NULL ON UPDATE CASCADE,
  ADD CONSTRAINT "cities_raion_id_fkey" FOREIGN KEY ("raion_id") REFERENCES "cities"("id") ON DELETE SET NULL ON UPDATE CASCADE,
  ADD COLUMN "name_ru_folded" TEXT GENERATED ALWAYS AS (kg_fold("name_ru")) STORED,
  ADD COLUMN "name_kg_folded" TEXT GENERATED ALWAYS AS (kg_fold("name_kg")) STORED,
  ADD COLUMN "aliases_folded" TEXT GENERATED ALWAYS AS (kg_fold_array("aliases")) STORED;

CREATE INDEX "cities_parent_id_idx" ON "cities" ("parent_id");
CREATE INDEX "cities_raion_id_idx" ON "cities" ("raion_id");
CREATE INDEX "cities_lat_lng_idx" ON "cities" ("lat", "lng") WHERE "is_searchable";
CREATE INDEX "cities_name_ru_folded_trgm_idx" ON "cities" USING gin ("name_ru_folded" gin_trgm_ops);
CREATE INDEX "cities_name_kg_folded_trgm_idx" ON "cities" USING gin ("name_kg_folded" gin_trgm_ops);
CREATE INDEX "cities_aliases_folded_trgm_idx" ON "cities" USING gin ("aliases_folded" gin_trgm_ops);

-- ─── 6. Place FKs + search / invariant indexes on ids ────────────────
ALTER TABLE "trips"
  ADD CONSTRAINT "trips_origin_city_id_fkey" FOREIGN KEY ("origin_city_id") REFERENCES "cities"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
  ADD CONSTRAINT "trips_destination_city_id_fkey" FOREIGN KEY ("destination_city_id") REFERENCES "cities"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "trip_stops"
  ADD CONSTRAINT "trip_stops_city_id_fkey" FOREIGN KEY ("city_id") REFERENCES "cities"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "passenger_requests"
  ADD CONSTRAINT "passenger_requests_origin_city_id_fkey" FOREIGN KEY ("origin_city_id") REFERENCES "cities"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
  ADD CONSTRAINT "passenger_requests_destination_city_id_fkey" FOREIGN KEY ("destination_city_id") REFERENCES "cities"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE INDEX "trip_stops_city_id_kind_idx" ON "trip_stops" ("city_id", "kind");
CREATE INDEX "trips_car_id_idx" ON "trips" ("car_id");
CREATE INDEX "idx_trips_active_search"
  ON "trips" ("origin_city_id", "destination_city_id", "departure_at") WHERE "status" = 'active';
CREATE INDEX "idx_trips_active_destination"
  ON "trips" ("destination_city_id", "departure_at") WHERE "status" = 'active';
-- Two old spellings (Джалал- / Жалал-Абад) can now be the same place: keep the
-- newest active trip / open request per driver + route + day, cancel the rest.
WITH dup AS (
  SELECT id, row_number() OVER (
    PARTITION BY driver_id, origin_city_id, destination_city_id, (departure_at AT TIME ZONE 'Asia/Bishkek')::date
    ORDER BY created_at DESC, id) AS rn
  FROM trips WHERE status = 'active'
), gone AS (
  UPDATE trips t SET status = 'cancelled', cancelled_reason = 'duplicate_route_day (directory migration)'
  FROM dup WHERE t.id = dup.id AND dup.rn > 1
  RETURNING t.id
)
UPDATE bookings b SET status = 'cancelled_by_driver', cancelled_by = 'driver', cancelled_at = NOW()
  FROM gone WHERE b.trip_id = gone.id AND b.status IN ('pending', 'viewed', 'accepted');
WITH dup AS (
  SELECT id, row_number() OVER (
    PARTITION BY passenger_id, origin_city_id, destination_city_id, (departure_date AT TIME ZONE 'Asia/Bishkek')::date
    ORDER BY created_at DESC, id) AS rn
  FROM passenger_requests WHERE status = 'open'
)
UPDATE passenger_requests r SET status = 'cancelled' FROM dup WHERE r.id = dup.id AND dup.rn > 1;

CREATE UNIQUE INDEX "idx_trips_route_day_unique"
  ON "trips" ("driver_id", "origin_city_id", "destination_city_id",
              ((departure_at AT TIME ZONE 'Asia/Bishkek')::date))
  WHERE "status" = 'active';

CREATE INDEX "idx_requests_open_search"
  ON "passenger_requests" ("origin_city_id", "destination_city_id", "departure_date") WHERE "status" = 'open';
CREATE INDEX "idx_requests_open_destination"
  ON "passenger_requests" ("destination_city_id", "departure_date") WHERE "status" = 'open';
CREATE UNIQUE INDEX "idx_requests_route_day_unique"
  ON "passenger_requests" ("passenger_id", "origin_city_id", "destination_city_id",
                           ((departure_date AT TIME ZONE 'Asia/Bishkek')::date))
  WHERE "status" = 'open';
